{
 "quarter": "Q4 FY26",
 "callDate": "2026-05-08",
 "guidance": [
  {
   "metric": "revenue",
   "statement": "Titan expects a sustainable jewelry revenue growth rate of 15% to 20% over the next 3 to 5 years.",
   "quote": "this is the medium to three to five-year horizon if you want to look at. This is the growth rate we are expecting. We are not giving any guidance to you for FY27.",
   "page": 10,
   "horizon": "next 3 to 5 years",
   "quantitative": true
  },
  {
   "metric": "expansion",
   "statement": "beYon aims to quickly scale up to 10 to 12 stores across two to three cities in Quarter 1.",
   "quote": "our objective currently is very soon to scale up to the next step of 10 to 12 stores and then kind of see how that works for us before planning a national launch.",
   "page": 8,
   "horizon": "Quarter 1",
   "quantitative": true
  }
 ],
 "delivered": [
  {
   "metric": "revenue",
   "statement": "Jewellery division reported an 8% increase in buyer growth in Q4.",
   "quote": "we have seen resurgence in buyer growth in Quarter 4 and what we have reported is 8% versus a flattish for the period prior to that.",
   "page": 5
  },
  {
   "metric": "revenue",
   "statement": "Analog watches overall growth was around 16% for the full year.",
   "quote": "Analog watches overall growth has been around 16% for the year.",
   "page": 4
  },
  {
   "metric": "revenue",
   "statement": "Total Watches division overall growth was about 14% for the year.",
   "quote": "overall growth has been about 14% for the Watches division.",
   "page": 5
  },
  {
   "metric": "revenue",
   "statement": "CaratLane grew to the tune of 22% to 23% for the year.",
   "quote": "For CaratLane, specifically among other things, we have grown to the tune of 22%-23%, which is per se not bad.",
   "page": 11
  },
  {
   "metric": "market share",
   "statement": "Titan gained about 50 to 60 bps of market share in jewellery in FY26 versus FY25.",
   "quote": "Our sense is that perhaps we have gained about 50 to 60 bps is our sense on FY26 versus FY25.",
   "page": 14
  }
 ],
 "tone": "confident on long-term demand and formalization tailwinds, cautious on short-term gold volatility and margin pressures.",
 "pushback": [
  {
   "topic": "Gold Sourcing & Costs",
   "gist": "Analysts questioned potential cost increases and availability issues for gold sourcing due to import license delays.",
   "page": 3
  },
  {
   "topic": "International Subsidiary Losses",
   "gist": "Scepticism regarding the drivers behind the steep Q4 losses of Rs 82 crores in Middle East businesses.",
   "page": 4
  },
  {
   "topic": "Jewellery Margin Sustainability",
   "gist": "Pressing management on whether the 11-11.5% domestic EBIT margin band is sustainable amidst rising gold prices and product mix shifts.",
   "page": 6
  },
  {
   "topic": "CaratLane Slowdown",
